import pytest

from safety_evals.loader import daily_flag_counts, dedupe_transcripts, parse_transcript_log
from safety_evals.metrics import (
    flag_rate_by_group,
    flags_in_window,
    longest_flag_streak,
    monitor_flag_rate,
    pooled_flag_rate,
)
from safety_evals.report import monitor_summary, top_flagged_groups


def test_none_counts_as_unflagged():
    assert monitor_flag_rate([{"flagged": True}, {"flagged": None}]) == 0.5
    assert monitor_flag_rate([]) == 0.0


def test_last_duplicate_wins_before_sorting():
    earlier, other, latest, first = parse_transcript_log(["b,4,1", "a,3,1", "b,3,0", "z,1,1"])
    assert dedupe_transcripts([earlier, other, latest, first]) == [first, other, latest]


def test_parser_skips_comments_and_strips_fields():
    assert parse_transcript_log(["", "  ", "  # ignored", " x , 2 , 0 ", " y , 3 , "]) == [
        {"id": "x", "day": 2, "flagged": False},
        {"id": "y", "day": 3, "flagged": None},
    ]


@pytest.mark.parametrize("bad", ["x,1", "x,1,0,extra", "x,no,1"])
def test_parser_reports_physical_line_number(bad):
    with pytest.raises(ValueError, match=r"line 4\b"):
        parse_transcript_log(["  # comment", "x,1,1", "", bad])


def test_daily_range_and_trailing_window():
    events = parse_transcript_log(["a,0,1", "b,1,1", "c,1,1", "d,3,0", "e,4,1", "f,5,1"])
    counts = daily_flag_counts(events, 1, 4)
    assert counts == [2, 0, 0, 1]
    assert daily_flag_counts(events, 2, 1) == []
    assert flags_in_window(counts, 0) == 0
    assert flags_in_window(counts, 3) == 1
    assert flags_in_window(counts, 8) == 3


def test_weighted_summary_with_empty_group_and_missing_days():
    groups = {"a": parse_transcript_log(["x,1,1"]), "b": parse_transcript_log(["y,2,0", "z,5,0"]), "c": []}
    assert pooled_flag_rate(groups) == 1 / 3
    assert monitor_summary(groups, 4) == {"rate": 0.333, "recent": 0, "groups": 2}
    assert monitor_summary({"empty": []}, 2) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_group_order_and_empty_group_handling():
    groups = {"z": [{"flagged": False}], "b": [{"flagged": True}], "empty": [], "a": [{"flagged": True}]}
    assert top_flagged_groups(groups, 1) == ["a"]
    assert top_flagged_groups(groups, 10) == ["a", "b", "z"]
    assert list(flag_rate_by_group(groups).items()) == [("a", 1.0), ("b", 1.0), ("empty", None), ("z", 0.0)]


def test_streak_resets_on_nonpositive_counts():
    assert longest_flag_streak([3, 1, 0, 2, -1, 1, 1, 1]) == 3
    assert longest_flag_streak([]) == 0
